-- twow-repo#295 W2a mount items (main train 9), owner decisions 2026-10-02 (#295, CLI-295):
--   "Reittier 1 kostet 1 g (Stufe 10/20), Reittier 2 kostet 100 g (Stufe 40/60)."
--   Family = today's item type: riding-75 item = family 1, riding-150 item or SPEED_100 mount
--   = family 2, ungated = spell base speed. Family 1 needs riding 75 from level 10, family 2
--   riding 225 from level 40. Mount 1 costs 1 g at the racial vendors (stage 10, riding 75),
--   mount 2 100 g (stage 40, riding 225). Special vendors (reputation quartermasters, PvP,
--   crabs, drake, Engineering mechs, Frostsaber) keep their prices. NPCs are never affected.
-- Built from the 01.10 live dump (+814) in a disposable DB: every item with required_skill 762
-- plus every collection item (spellid_1 46499, mount spell from collection_mount): 429 items.
--   49 + 3 family-1 items (riding 75, level 40 / 60) -> level 10
--   73 family-2 items (riding 150, level 60) -> riding 225, level 40
--   8 + 5 SPEED_100 mounts with riding 75 (the Black War mounts, level 40; Winterspring
--     Frostsaber and the four AQ40 crystals, level 60) -> family 2, riding 225, level 40
--   32 family-1 items of the racial vendors 1261, 1460, 62184, template 1500032
--     (384/2357/4885), 3362, 3685, 4730, 4731, 7952, 7955, 80453, 80137: buy 100000 -> 10000.
--     The rocket cars 80460-80462 sell back for 0 instead of 20000, owner decision 2026-10-02:
--     "0 wie alle Rassen-Tiere" (every other racial family-1 mount sells for 0; buying for 1 g
--     and selling for 2 g would create money). Family-2 racial mounts stay at 1000000.
--     Not a racial vendor: 80811 Zul'Mabe Bearclaw is a reputation vendor (faction 893
--     Revantusk Trolls, Exalted); its family-2 bears keep their prices (1000000 / 3000000).
--   146 + 129 ungated collection mounts (family 1 / 2 by spell speed) keep their requirements.
--   Item text: one sentence is appended to the description of all 413 items above
--   (198 family 1, 215 family 2); the 1.12 client shows it inside the quotes.
-- Unchanged on purpose (listed in the manifest):
--   data defects, not fixed here: 36532, 80456, 92018 (no collection_mount row), 50402, 50404,
--   81242 (two collection_mount rows), 92052 (maps to 57577 like 92054), 81237 (riding 150 but
--   a +60 spell), 50405 (maps to the tallstrider 10801);
--   16339 Commander's Steed (riding 150, not obtainable) shares its mount spell 16082 with the
--   family-1 racial mount 12354, which 20261002212000 turns into +60;
--   the Engineering mechs 81190-81195 (Engineering 300);
--   mount items without riding 762 and without 46499 (deprecated, test, old PvP): 823, 842,
--   875, 901-903, 1042-1044, 1122-1124, 12330, 14062, 16338, 16343, 16344, 18063, 20221, 21736.
-- Manifest (item, old/new rank, level, price, family, vendor, source, decision):
-- builds/cli295-riding/evidence/manifest/mount-items-295.tsv. The mount spells themselves
-- change in 20261002212000 (the 12 riding-75 items with a +100 spell become +60 there).
-- This file touches item_template only, so its item entries never count as spell IDs.
-- Replay-safe: the backup takes only rows without the appended sentence; every update checks
-- the old values; the tail asserts the end state.
-- W1, W2a, W2b and W3 are rolled back together (newest file first); after go-live also with
-- the character step in the 20261002210000 header (riding capped at 150).
-- Rollback (exact SQL; item_template_bak_295 stays for a later cleanup):
--   UPDATE `item_template` i JOIN `item_template_bak_295` b ON b.`entry` = i.`entry`
--      SET i.`required_skill` = b.`required_skill`, i.`required_skill_rank` = b.`required_skill_rank`,
--          i.`required_level` = b.`required_level`, i.`buy_price` = b.`buy_price`,
--          i.`sell_price` = b.`sell_price`, i.`description` = b.`description`;

CREATE TABLE IF NOT EXISTS `item_template_bak_295` LIKE `item_template`;
